with scored as (select id, store_name, city, dense_rank() over w_running as sqft_dense_rank, sum(sqft) over (partition by city, region order by sqft, id rows between unbounded preceding and current row) as running_sqft, ntile(4) over (partition by region, city order by sqft desc, id) as sqft_bucket from stores window w_running as (partition by region order by sqft nulls first)) select case when sqft_dense_rank >= 7 then 'PREMIUM' else 'STANDARD' end as sqft_dense_rank_tier, size(collect_set(city)) as num_cities, sum(running_sqft) as total_running_sqft, max(sqft_dense_rank) as max_sqft_dense_rank from scored group by case when sqft_dense_rank >= 7 then 'PREMIUM' else 'STANDARD' end order by num_cities nulls last
